<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>STUMPS Control Center</title><style>body{font-family:system-ui;margin:0;background:#07111f;color:#e5e7eb}.wrap{max-width:1100px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;align-items:center}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px}.card{background:#111d30;border:1px solid #263850;border-radius:16px;padding:20px;margin:18px 0}.metric b{font-size:28px;color:#4ade80}.row{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid #263850}select,button{padding:10px;border-radius:8px}button{background:#22c55e;border:0;font-weight:700}.danger{color:#fca5a5}.ok{color:#86efac}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #263850}</style></head><body><div class="wrap"><div class="top"><div><h1>STUMPS Control Center</h1><span class="ok">API connected</span></div><form method="post" action="{{ route('admin.logout') }}">@csrf<button>Logout</button></form></div>@if(session('status'))<div class="card ok">{{ session('status') }}</div>@endif<div class="grid">@foreach($metrics as $label=>$value)<div class="card metric"><span>{{ ucfirst(preg_replace('/([A-Z])/', ' $1', $label)) }}</span><br><b>{{ $value }}</b></div>@endforeach</div><form class="card" method="post" action="{{ route('admin.controls.update') }}">@csrf @method('PUT')<h2>API Controls</h2><div class="row"><span>New registrations</span><select name="registration_enabled"><option value="1" @selected($controls['registration_enabled'])>Enabled</option><option value="0" @selected(!$controls['registration_enabled'])>Disabled</option></select></div><div class="row"><span>Write operations</span><select name="api_read_only"><option value="0" @selected(!$controls['api_read_only'])>Enabled</option><option value="1" @selected($controls['api_read_only'])>Read-only emergency mode</option></select></div><div class="row"><span>Rollout stage</span><select name="rollout_stage">@foreach(['internal_alpha','closed_beta','tournament_beta','production'] as $stage)<option @selected($controls['rollout_stage']===$stage)>{{ $stage }}</option>@endforeach</select></div><p class="danger">Read-only mode blocks API mutations except login/logout.</p><button>Save audited controls</button></form><div class="card"><h2>Recent Admin Audit</h2><table><tr><th>Time</th><th>Action</th><th>IP</th></tr>@forelse($auditLogs as $log)<tr><td>{{ $log->created_at }}</td><td>{{ $log->action }}</td><td>{{ $log->ip_address }}</td></tr>@empty<tr><td colspan="3">No admin changes yet.</td></tr>@endforelse</table></div></div></body></html>
